+        let batch: Vec<SimOp> = ops[i..end].iter().map(|o| o.0).collect();
+        if drill {
+            held.simulate_drill(&batch)?;
+        } else {
+            held.simulate(&batch)?;
+        }
+        i = end;
     }
+    Ok(())
