+    let tc = if l2 > 0.0 { ((rho * r + zl * h) / l2).clamp(0.0, 1.0) } else { 0.0 };
+    let dist_cone = (rho - tc * r).hypot(zl - tc * h);
+    let dist_cyl = (rho - r).max(0.0).hypot(zl - zl.clamp(h, f));
+    dist_cone.min(dist_cyl)
